using System;using System.IO;using System.Xml;using System.Drawing;
namespace BeamScheduleFormatter {
enum AppearanceMode { System, Light, Dark }
static class AppearancePreferences {
 public static string PathName {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DTCE","ToolKit","Appearance.xml");}}
 public static AppearanceMode Read(string path){if(!File.Exists(path))return AppearanceMode.System;var doc=new XmlDocument{XmlResolver=null};using(var reader=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=10000}))doc.Load(reader);var root=doc.DocumentElement;AppearanceMode mode;if(root==null||root.Name!="DesktopAppearance"||root.GetAttribute("version")!="1"||!Enum.TryParse(root.GetAttribute("mode"),false,out mode)||!Enum.IsDefined(typeof(AppearanceMode),mode))throw new Exception("Invalid desktop appearance setting.");return mode;}
 public static void Write(string path,AppearanceMode mode){if(!Enum.IsDefined(typeof(AppearanceMode),mode))throw new ArgumentException("Unknown appearance option.");var doc=new XmlDocument();var root=doc.CreateElement("DesktopAppearance");doc.AppendChild(root);root.SetAttribute("version","1");root.SetAttribute("mode",mode.ToString());string directory=Path.GetDirectoryName(Path.GetFullPath(path));Directory.CreateDirectory(directory);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{doc.Save(temp);if(File.Exists(path))File.Replace(temp,path,path+".bak");else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
 public static bool ResolveDark(AppearanceMode mode,bool systemLight){if(!Enum.IsDefined(typeof(AppearanceMode),mode))throw new ArgumentException("Unknown appearance option.");return mode==AppearanceMode.Dark||(mode==AppearanceMode.System&&!systemLight);}
}
sealed class DesktopPalette {
 public readonly bool Dark;public readonly Color Background,Surface,Input,Ink,Muted,Line,Accent,AccentHover,Selected,Link,Soft,Header,Chrome,ChromeButton,TabMain,TabSub,TabNested;
 public DesktopPalette(bool dark){Dark=dark;if(dark){Background=C(24,29,37);Surface=C(29,36,46);Input=C(35,48,66);Ink=C(225,231,239);Muted=C(164,177,194);Line=C(67,77,91);Accent=C(61,86,110);AccentHover=C(75,103,130);Selected=C(47,70,99);Link=C(174,196,216);Soft=C(33,41,52);Header=C(37,46,59);Chrome=C(18,35,52);ChromeButton=C(28,48,67);TabMain=C(32,52,77);TabSub=C(32,61,57);TabNested=C(69,57,41);}else{/* Studio look (owner, 20 November 2026: the whole app like POW Studio - "cohesive and professional", "hindi masakit sa
   mata"): white work surfaces on a soft green-grey page, deep green chrome, one green accent, hairline dividers */Background=C(244,247,245);Surface=C(255,255,255);Input=C(250,252,251);Ink=C(32,49,46);Muted=C(88,103,96);Line=C(221,229,224);Accent=C(35,117,86);AccentHover=C(27,97,70);Selected=C(224,240,232);Link=C(35,117,86);Soft=C(240,245,242);Header=C(250,252,251);Chrome=C(20,56,44);ChromeButton=C(43,93,71);/* folder tabs keep their own tints (owner, 20 November 2026: "mas okay pa din yung folder tabs ang itsura") */TabMain=C(211,225,242);TabSub=C(215,235,225);TabNested=C(242,231,209);}}
 static Color C(int r,int g,int b){return Color.FromArgb(r,g,b);}
 public Color Tab(int depth){return depth==0?TabMain:depth==1?TabSub:TabNested;}
 public Color ActiveTab(int depth){return depth==0?C(43,76,116):depth==1?C(40,94,76):C(107,77,39);}
 public Color ActiveTabText {get{return Color.White;}}
 public Color Translate(Color value,DesktopPalette from){if(value.IsEmpty||value.A==0)return value;Color[] before={from.Background,from.Surface,from.Input,from.Ink,from.Muted,from.Line,from.Accent,from.AccentHover,from.Selected,from.Link,from.Soft,from.Header,from.Chrome,from.ChromeButton,from.TabMain,from.TabSub,from.TabNested};Color[] after={Background,Surface,Input,Ink,Muted,Line,Accent,AccentHover,Selected,Link,Soft,Header,Chrome,ChromeButton,TabMain,TabSub,TabNested};for(int i=0;i<before.Length;i++)if(value.ToArgb()==before[i].ToArgb())return after[i];return value;}
}
}
